package com.university.scheduler.ui;
import com.university.scheduler.dao.UiRepository;import com.university.scheduler.model.*;import javafx.collections.*;import javafx.geometry.*;import javafx.scene.Parent;import javafx.scene.control.*;import javafx.scene.layout.*;import java.sql.SQLException;
public class RoomView{
 private final ObservableList<Room> rows=FXCollections.observableArrayList();private final TableView<Room> table=new TableView<>();
 public Parent getView(){VBox root=UiSupport.page("Rooms Management","Manage classrooms, laboratories and learning spaces.");TextField search=UiSupport.field("Search room ID or name");Button add=new Button("+ Add Room"),refresh=new Button("Refresh");add.getStyleClass().add("primary-button");HBox bar=new HBox(10,search,refresh,add);bar.setAlignment(Pos.CENTER_LEFT);HBox.setHgrow(search,Priority.ALWAYS);
 table.getColumns().addAll(UiSupport.col("Room ID",Room::getRoomId),UiSupport.col("Room Name",Room::getRoomName),UiSupport.col("Type",r->r.getRoomType().name()),UiSupport.col("Capacity",r->String.valueOf(r.getCapacity())));UiSupport.style(table);table.setItems(rows);
 TableColumn<Room,Void> actions=new TableColumn<>("Actions");actions.setCellFactory(c->new TableCell<>(){final Button edit=new Button("Edit"),del=new Button("Delete");final HBox box=new HBox(6,edit,del);{edit.setOnAction(e->dialog(getTableView().getItems().get(getIndex())));del.setOnAction(e->{Room r=getTableView().getItems().get(getIndex());if(UiSupport.confirm("Delete room "+r.getRoomId()+"?"))try{UiRepository.deleteRoom(r.getRoomId());load();}catch(Exception ex){UiSupport.error("Could not delete room",ex);}});}protected void updateItem(Void v,boolean empty){super.updateItem(v,empty);setGraphic(empty?null:box);}});table.getColumns().add(actions);
 search.textProperty().addListener((o,a,b)->table.setItems(rows.filtered(r->(r.getRoomId()+r.getRoomName()).toLowerCase().contains(b.toLowerCase()))));add.setOnAction(e->dialog(null));refresh.setOnAction(e->load());root.getChildren().addAll(bar,table);VBox.setVgrow(table,Priority.ALWAYS);load();return root;}
 private void load(){try{rows.setAll(UiRepository.rooms());table.setItems(rows);}catch(Exception e){UiSupport.error("Database connection failed while loading rooms",e);}}
 private void dialog(Room old){Dialog<ButtonType>d=new Dialog<>();d.setTitle(old==null?"Add Room":"Edit Room");ButtonType save=new ButtonType("Save",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(save,ButtonType.CANCEL);TextField id=UiSupport.field("Room ID"),name=UiSupport.field("Room name"),capacity=UiSupport.field("Capacity");ComboBox<RoomType> type=new ComboBox<>(FXCollections.observableArrayList(RoomType.values()));type.setValue(RoomType.CLASSROOM);if(old!=null){id.setText(old.getRoomId());id.setDisable(true);name.setText(old.getRoomName());capacity.setText(String.valueOf(old.getCapacity()));type.setValue(old.getRoomType());}GridPane g=new GridPane();g.setHgap(10);g.setVgap(10);g.addRow(0,new Label("Room ID"),id);g.addRow(1,new Label("Name"),name);g.addRow(2,new Label("Type"),type);g.addRow(3,new Label("Capacity"),capacity);d.getDialogPane().setContent(g);d.showAndWait().ifPresent(b->{if(b==save)try{int n=Integer.parseInt(capacity.getText().trim());if(id.getText().isBlank()||name.getText().isBlank()||n<1)throw new IllegalArgumentException("Enter valid room details and positive capacity.");UiRepository.saveRoom(new Room(id.getText().trim(),name.getText().trim(),type.getValue(),n),old!=null);load();}catch(Exception ex){UiSupport.error("Could not save room",ex);}});}
}
